import https from 'node:https';import http from 'node:http';import {readFileSync} from 'node:fs';
const port=Number(process.env.NODENO_QA_PORT),upstream=Number(process.env.NODENO_QA_UPSTREAM);if(!Number.isInteger(port)||port<1024||!Number.isInteger(upstream)||upstream<1024)throw new Error('Isolated preview ports required');
https.createServer({key:readFileSync(process.env.NODENO_QA_KEY),cert:readFileSync(process.env.NODENO_QA_CERT)},(req,res)=>{const relay=http.request({host:'127.0.0.1',port:upstream,path:req.url,method:req.method,agent:false,headers:{...req.headers,connection:'close'}},response=>{res.writeHead(response.statusCode,{...response.headers,connection:'close'});response.pipe(res);});relay.on('error',()=>{res.writeHead(502);res.end();});req.pipe(relay);}).listen(port,'127.0.0.1');
